// B.1 STEP 1: Normalize Intake & Generate Identifiers
const rawBody = $input.first().json.body || $input.first().json;

const fullName = (rawBody.full_name || rawBody.name || '').trim().replace(/\s+/g, ' ');
const email = (rawBody.email || '').toLowerCase().trim();
const companyName = (rawBody.company_name || rawBody.company || 'Not Specified').trim().replace(/\s+/g, ' ');
const serviceInterest = (rawBody.service_interest || rawBody.service || 'AI Automation').trim();
const problemDescription = (rawBody.problem_description || rawBody.problem || '').trim();

let rawPhone = String(rawBody.phone || '');
let phone = rawPhone.replace(/[^\d+]/g, '');
if (phone.length === 10 && !phone.startsWith('+')) {
  phone = `+91${phone}`;
}

const leadUid = `luid-${Date.now()}-${Math.random().toString(36).substring(2, 8)}`;
const idempotencyKey = `experience_service:${email}`;

return [{
  json: {
    lead_uid: leadUid,
    idempotency_key: idempotencyKey,
    full_name: fullName,
    name: fullName,
    email,
    phone,
    company_name: companyName,
    service_interest: serviceInterest,
    problem_description: problemDescription,
    source: 'experience_service',
    status: 'new_lead',
    qualification_status: 'pending',
    meeting_booked: false
  }
}];

