// B.2 STEP 1 & 2: Verify & Parse Bolna Qualification Callback
const rawBody = $input.first().json.body || $input.first().json;
const callData = rawBody.data || rawBody.user_data || rawBody;

const leadUid = callData.lead_uid || callData.user_data?.lead_uid || '';
const callSid = rawBody.execution_id || rawBody.call_id || rawBody.id || `bolna-call-${Date.now()}`;
const qualStatus = (rawBody.qualification_status || callData.qualification_status || 'qualified').toLowerCase().trim();
const summary = rawBody.summary || rawBody.call_summary || 'Bolna AI Qualification Call completed cleanly.';
const transcript = rawBody.transcript || rawBody.conversation_log || 'AI Voice Call completed.';
const recordingUrl = rawBody.recording_url || rawBody.audio_url || '';
const durationSec = Number(rawBody.duration || rawBody.duration_sec || 60);
const budgetSignal = rawBody.budget || rawBody.budget_range || 'Standard Package';
const urgency = rawBody.urgency || 'Normal';
const callOutcome = (qualStatus === 'qualified' || qualStatus === 'follow_up') ? 'answered' : (qualStatus || 'no_answer');

if (!leadUid) {
  throw new Error('Callback verification failed: missing lead_uid');
}

return [{
  json: {
    lead_uid: leadUid,
    call_sid: callSid,
    qualification_status: qualStatus,
    call_summary: summary,
    call_transcript: transcript,
    call_recording_url: recordingUrl,
    call_duration_sec: durationSec,
    budget_signal: budgetSignal,
    urgency,
    call_answered: (callOutcome === 'answered'),
    call_outcome: callOutcome,
    is_qualified: (qualStatus === 'qualified')
  }
}];

