// B.3 STEP 7: Parse & Save Scores
const rawGpt = $input.first().json.choices?.[0]?.message?.content || '{}';
let parsed = {};
try {
  parsed = JSON.parse(rawGpt);
} catch(e) {
  parsed = { fit_score: 15, intent_score: 15, urgency_score: 15, budget_score: 15, lead_score: 75, temperature: 'warm', reason: 'Evaluated lead for House of Workflow fit.' };
}

const leadScore = Math.min(100, Math.max(0, Number(parsed.lead_score) || 75));
let temperature = (parsed.temperature || 'warm').toLowerCase();
if (leadScore >= 80) temperature = 'hot';
else if (leadScore < 50) temperature = 'cold';

return [{
  json: {
    fit_score: parsed.fit_score || 15,
    intent_score: parsed.intent_score || 15,
    urgency_score: parsed.urgency_score || 15,
    budget_score: parsed.budget_score || 15,
    lead_score: leadScore,
    lead_temperature: temperature,
    lead_score_reason: parsed.reason || `Calculated lead score as ${leadScore}/100 (${temperature}).`,
    is_hot: (leadScore >= 80)
  }
}];

// B.4 STEP 2: Analyze & Choose Earliest Available Slot (Dynamic Parsing)
const rawRes = $input.first().json;
const slotsMap = rawRes.data?.slots || rawRes.slots || {};

let selectedStartIso = null;
let selectedEndIso = null;

// Iterate through dynamic dates array
const dates = Object.keys(slotsMap).sort();
for (const dateKey of dates) {
  const daySlots = slotsMap[dateKey] || [];
  if (daySlots.length > 0) {
    const slot = daySlots[0];
    selectedStartIso = slot.start || slot.time;
    selectedEndIso = slot.end || new Date(new Date(selectedStartIso).getTime() + 30 * 60000).toISOString();
    break;
  }
}

// Fallback: If no API slots found, calculate next business day 11:00 AM Asia/Kolkata
if (!selectedStartIso) {
  const d = new Date();
  d.setDate(d.getDate() + 1);
  d.setHours(11, 0, 0, 0);
  selectedStartIso = d.toISOString();
  selectedEndIso = new Date(d.getTime() + 30 * 60000).toISOString();
}

const startDateObj = new Date(selectedStartIso);
const formattedDate = startDateObj.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
const formattedTime = startDateObj.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });

return [{
  json: {
    selected_start: selectedStartIso,
    selected_end: selectedEndIso,
    formatted_date: formattedDate,
    formatted_time: formattedTime
  }
}];

